SELECT * FROM logs WHERE EventID=1 AND (EventID=1 AND ((ParentImage LIKE '%\\WINWORD.EXE' ESCAPE '\' OR ParentImage LIKE '%\\EXCEL.EXE' ESCAPE '\' OR ParentImage LIKE '%\\POWERPNT.EXE' ESCAPE '\' OR ParentImage LIKE '%\\OUTLOOK.EXE' ESCAPE '\') AND (Image LIKE '%\\cmd.exe' ESCAPE '\' OR Image LIKE '%\\powershell.exe' ESCAPE '\' OR Image LIKE '%\\pwsh.exe' ESCAPE '\' OR Image LIKE '%\\wscript.exe' ESCAPE '\' OR Image LIKE '%\\cscript.exe' ESCAPE '\' OR Image LIKE '%\\mshta.exe' ESCAPE '\' OR Image LIKE '%\\rundll32.exe' ESCAPE '\' OR Image LIKE '%\\regsvr32.exe' ESCAPE '\' OR Image LIKE '%\\certutil.exe' ESCAPE '\' OR Image LIKE '%\\bitsadmin.exe' ESCAPE '\' OR Image LIKE '%\\schtasks.exe' ESCAPE '\' OR Image LIKE '%\\PING.EXE' ESCAPE '\') AND (NOT COALESCE((CommandLine LIKE '%\\fs01.corp.local\\reports\\%' ESCAPE '\'), 0))))
